def _make(name, ctor, args, fixed, input_size):
    def entry(**kwargs):
        model = ctor(*args, **fixed, **kwargs)
        model.default_cfg = _cfg(input_size=input_size)
        return model
    entry.__name__ = name
    entry.__module__ = ctor.__module__
    return entry

